  int n,x;
  mint d,s,ans;

  cin>>n;
  fenwick_tree<mint> fw1(M+1);
  fenwick_tree<mint> fw2(M+1);
  s=0;
  for(int i=0;i<n;i++){
    cin>>x;
    d=fw1.sum(0,x+1)*mint(x)+fw2.sum(x+1,M+1);
